SELECT DISTINCT l1.product_id, l1.amount, SUM(o.total) AS total FROM (
  SELECT lines.product_id, lines.amount,
    SUM(CASE WHEN lines.unit_price = p.price THEN lines.units ELSE NULL END) OVER (PARTITION BY lines.order_id, lines.sku ORDER BY lines.order_id) AS amount
